package com.realstant.nativegame; import android.content.*; public final class ProfileStore { private final SharedPreferences p; public ProfileStore(Context c){p=c.getSharedPreferences("profile",0);} public void load(Profile x){x.nickname=p.getString("name","Driver");x.level=p.getInt("level",1);x.xp=p.getInt("xp",0);} public void save(Profile x){p.edit().putString("name",x.nickname).putInt("level",x.level).putInt("xp",x.xp).apply();} }
